{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.instamart_fact_item as WITH sku_mapping AS ( SELECT TRIM(CAST(ITEM_CODE AS STRING)) AS item_code, MAX(TRIM(SKU)) AS mapped_sku FROM snitch_db.maplemonk.gs_ITEM_CODE_SKU_MAPPING_INSTA_Sheet1 GROUP BY 1 ), sp_data AS ( SELECT TRIM(CAST(ITEM_CODE AS STRING)) AS item_code, TO_DATE(DT, \'DD-MM-YYYY\') AS sp_date, SUM(TRY_TO_NUMBER(REPLACE(QUANTITY, \',\', \'\'))) AS total_qty, SUM(TRY_TO_NUMBER(REPLACE(TOTAL_SALES_AMOUNT, \',\', \'\'))) AS total_sales_val FROM snitch_db.maplemonk.S3_INSTAMART_SP GROUP BY 1, 2 ), raw_sales AS ( SELECT TRIM(CAST(ITEM_CODE AS STRING)) AS item_code, TO_DATE(ORDERED_DATE, \'DD-MM-YYYY\') AS order_date, MAX(PRODUCT_NAME) AS product_name, SUM(TRY_TO_NUMBER(REPLACE(UNITS_SOLD, \',\', \'\'))) AS total_quantity, MAX(TRY_TO_NUMBER(REPLACE(BASE_MRP, \',\', \'\'))) AS base_mrp FROM snitch_db.maplemonk.S3_INSTAMART_SALES GROUP BY 1, 2 ), joined_sales AS ( SELECT s.item_code, m.mapped_sku AS sku, REGEXP_REPLACE(REPLACE(UPPER(TRIM(m.mapped_sku)), \'-SHIRT\', \'\'), \'-[^-]*$\', \'\') AS sku_group, s.order_date, s.total_quantity, s.base_mrp, CASE WHEN sp.total_qty > 0 THEN (sp.total_sales_val / sp.total_qty) ELSE s.base_mrp END AS calculated_sp, s.product_name FROM raw_sales s LEFT JOIN sp_data sp ON s.item_code = sp.item_code AND s.order_date = sp.sp_date LEFT JOIN sku_mapping m ON s.item_code = m.item_code WHERE m.mapped_sku IS NOT NULL ), agg_returns AS ( SELECT NULL::STRING AS sku, NULL::STRING AS sku_group, NULL::DATE AS latest_return_date, 0::INT AS RETURN_QUANTITY, 0::INT AS return_price, NULL::STRING AS return_product_name, NULL::STRING AS return_product_url WHERE 1=0 ), metafields AS ( SELECT * FROM ( SELECT *, UPPER(TRIM(sku_group)) as clean_sku_group, ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(sku_group)) ORDER BY status DESC) AS rn FROM snitch_db.maplemonk.metafields_data ) mf WHERE rn = 1 ), availability AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(\"Item SkuCode\")), \'-[^-]*$\', \'\') as clean_sku_group, MAX(\"MRP\") as mrp FROM snitch_db.maplemonk.snitch_final_inventory_wh2 GROUP BY 1 ) SELECT COALESCE(s.sku, r.sku) AS sku, COALESCE(s.sku_group, r.sku_group) AS sku_group, REGEXP_SUBSTR(COALESCE(s.sku, r.sku), \'[^-]+$\') AS SIZE, COALESCE(s.order_date, r.latest_return_date) AS order_date, COALESCE(s.total_quantity, 0) AS TOTAL_QUANTITY, COALESCE(s.calculated_sp, 0) AS selling_price, COALESCE(s.base_mrp, a.mrp) AS mrp, (COALESCE(s.base_mrp, a.mrp) - COALESCE(s.calculated_sp, 0)) AS discount, COALESCE(s.product_name, r.return_product_name, \'-\') AS product_name, \'-\' AS color_family, \'-\' AS product_url, r.latest_return_date, COALESCE(r.RETURN_QUANTITY, 0) AS RETURN_QUANTITY, COALESCE(r.return_price, 0) AS return_price, COALESCE(r.return_product_name, s.product_name, \'-\') AS return_product_name, COALESCE(r.return_product_url, \'-\', \'-\') AS return_product_url, m.category, m.title, m.material_new, m.print_design, m.fit, m.sleeve_type, m.collar_new FROM joined_sales s FULL OUTER JOIN agg_returns r ON s.sku = r.sku AND s.order_date = r.latest_return_date LEFT JOIN metafields m ON COALESCE(s.sku_group, r.sku_group) = m.clean_sku_group LEFT JOIN availability a ON COALESCE(s.sku_group, r.sku_group) = a.clean_sku_group;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            